[
  {
    "title": "fight-button-overlaps-fighters",
    "claim": "In Image #14, the FIGHT button overlaps the lower portions of both fighters’ inward-facing legs.",
    "reason": "The introduction obscures part of the fighters’ silhouettes before the player begins.",
    "suggest": "Place the FIGHT button within the introduction’s text area, clear of both fighter silhouettes."
  },
  {
    "title": "intro-controls-lack-instructions",
    "claim": "Image #2 labels the sticks STANCE and TECHNIQUE but does not show the action mappings that are visible in Image #3.",
    "reason": "The player sees the invitation to fight before seeing which directions perform which actions.",
    "suggest": "Show the directional action legend during the qualifier introduction, not only in the fighting view."
  },
  {
    "title": "direction-symbols-disagree",
    "claim": "In Image #5, the stick sectors use chevrons while the instruction panel uses filled triangles for the corresponding directions.",
    "reason": "Players must translate between two visual representations of the same inputs.",
    "suggest": "Use matching direction words on the stick sectors and in the legend, with action-specific Font Awesome icons where useful."
  },
  {
    "title": "result-poses-lack-outcome-distinction",
    "claim": "In Image #18, ASMONGOLD WINS appears above Asmongold in a kicking pose and HasanAbi in a guard pose rather than visually distinct outcome poses.",
    "reason": "The text communicates victory, but the fighter presentation still resembles an exchange.",
    "suggest": "Give the result presentation a winner salute and a distinct loser recovery pose; this frame alone does not establish whether either existing animation is frozen."
  },
  {
    "title": "technique-text-size-unverified",
    "claim": "In Image #6, the scoring metadata appears smaller than the technique names, but their exact CSS font sizes cannot be established from this screenshot.",
    "reason": "Height and point value are essential information when choosing a technique, so their readability needs verification.",
    "suggest": "Measure computed font sizes for the technique names, scoring metadata, and legends at 390×844; raise anything below 18 CSS px and stack metadata beneath names if necessary."
  }
]
